/// The record for `ty` in schema `id`, or, where no file of that schema showed the type, in the
/// nearest schema that has it (the older on a tie).
pub(super) fn record(id: u32, ty: u16) -> Option<&'static [u8]> {
    SCHEMAS
        .iter()
        .filter_map(|(s, recs)| {
            let r = recs.iter().find(|r| r.0 == ty)?;
            Some(((s.abs_diff(id), *s > id), r.1))
        })
        .min_by_key(|x| x.0)
        .map(|x| x.1)
}
